import{_ as l}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as c,c as h,o,af as a,b as i,w as e,a as r,G as s,ag as d}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const v=JSON.parse('{"title":"Protocol Map","description":"The interoperability-group protocol selection entry, grouped by connection direction — MCP for Agent↔tools, ACP for Editor↔coding agent, AG-UI for Agent↔user, A2A for Agent↔Agent; with the ACP triple-homonym disambiguation and a combination decision table.","frontmatter":{"title":"Protocol Map","description":"The interoperability-group protocol selection entry, grouped by connection direction — MCP for Agent↔tools, ACP for Editor↔coding agent, AG-UI for Agent↔user, A2A for Agent↔Agent; with the ACP triple-homonym disambiguation and a combination decision table.","domain":"tech","tags":["tech","action","protocols","map"],"navOrder":70,"topicId":"protocol-map","layer":"7","status":"canonical","nodeType":"pattern","owner":"learn-ai","externalOwners":[],"prerequisites":["tool-execution"],"next":["mcp","a2a","acp-agent-client","ag-ui","a2ui-mcp-apps"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/07-interoperability/index.md","filePath":"tech/07-interoperability/index.md","lastUpdated":1791117695000}'),p={name:"tech/07-interoperability/index.md"};function u(m,t,g,f,A,b){const n=c("Mermaid");return o(),h("div",null,[t[2]||(t[2]=a('<blockquote><p><strong>Group</strong>: Interoperability | <strong>Exit of the group above</strong>: you can wire model output into sessions and state | <strong>Exit of this group</strong>: given a cross-boundary requirement you can pick the protocol by connection direction and justify rejecting the rest <strong>Prerequisites</strong>: <a href="./../05-action/tool-execution.html">Tool Execution Engineering</a>, <a href="./../00-map/complexity-ladder.html">Complexity Decision Ladder</a> | <strong>Next</strong>: proceed by map to <a href="./mcp.html">MCP</a>, <a href="./a2a.html">A2A</a>, <a href="./acp-agent-client.html">ACP</a>, <a href="./ag-ui.html">AG-UI</a>, <a href="./a2ui-mcp-apps.html">A2UI and MCP Apps</a></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>Lead with the answer</strong>: the protocols of the interoperability group are not competitors; they <strong>each occupy one connection direction</strong>. The first selection question is not &quot;which protocol is better&quot; but &quot;<strong>what are the two ends I am connecting</strong>&quot;: agent to tools, editor to coding agent, agent to user interface, or agent to agent. Once the direction is fixed, the candidate set usually shrinks to one; trust domain and state needs then confirm the choice.</p><h3 id="mental-model-grouped-by-connection-direction" tabindex="-1">Mental model: grouped by connection direction <a class="header-anchor" href="#mental-model-grouped-by-connection-direction" aria-label="Permalink to &quot;Mental model: grouped by connection direction&quot;">​</a></h3>',4)),(o(),i(d,null,{default:e(()=>[s(n,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20USER%5B%22User%20%2F%20app%22%5D%20%3C--%20%22AG-UI%3Cbr%2F%3E(events%2Fstate%2Finterrupts)%22%20--%3E%20AGENT%5B%22your%20agent%22%5D%0A%20%20%20%20EDITOR%5B%22Editor%20%2F%20IDE%22%5D%20%3C--%20%22ACP%3Cbr%2F%3E(Agent%20Client%20Protocol)%22%20--%3E%20CAGENT%5B%22coding%20agent%22%5D%0A%20%20%20%20AGENT%20%3C--%20%22MCP%3Cbr%2F%3E(tools%2Fresources%2Fprompts)%22%20--%3E%20TOOLS%5B%22tools%20%2F%20data%22%5D%0A%20%20%20%20AGENT%20%3C--%20%22Skills%3Cbr%2F%3E(knowledge%20packaging%2C%20not%20a%20protocol)%22%20--%3E%20KNOW%5B%22reusable%20procedural%20knowledge%22%5D%0A%20%20%20%20AGENT2%5B%22another%20org's%20agent%22%5D%20%3C--%20%22A2A%3Cbr%2F%3E(Card%2FTask%2FArtifact)%22%20--%3E%20AGENT%0A%20%20%20%20AGENT%20%3C--%20%22A2UI%20%2F%20MCP%20Apps%3Cbr%2F%3E(rendered%20UI)%22%20--%3E%20UI%5B%22rendered%20interface%22%5D%0A%20%20%20%20subgraph%20OBS%5B%22Observation%20zone%20(watchlist)%22%5D%0A%20%20%20%20%20%20%20%20ARD%5B%22ARD%20%2F%20MCP%20Registry%3Cbr%2F%3Ediscovery%22%5D%0A%20%20%20%20%20%20%20%20COMMERCE%5B%22UCP%20%2F%20AP2%20%2F%20x402%3Cbr%2F%3Ecommerce%22%5D%0A%20%20%20%20end%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[r(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=a('<p>Note: <strong>Skills are not a protocol</strong> — they are a knowledge packaging format (no wire layer), drawn here only to occupy the &quot;reusable knowledge&quot; direction; <a href="./../06-agent-systems/plugins.html">Plugins</a> likewise occupies the &quot;capability bundling&quot; direction.</p><h3 id="protocol-landscape-table" tabindex="-1">Protocol landscape table <a class="header-anchor" href="#protocol-landscape-table" aria-label="Permalink to &quot;Protocol landscape table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Connection direction</th><th>Protocol/format</th><th>Status</th><th>One-line responsibility</th><th>Detail</th></tr></thead><tbody><tr><td>Reusable knowledge → agent</td><td>Agent Skills</td><td>canonical</td><td>instruction + resource packaging with progressive disclosure</td><td><a href="./../06-agent-systems/skills.html">Skills</a></td></tr><tr><td>Capability bundle → distributable</td><td>Agent Plugins</td><td>watchlist</td><td>plugin.json manifest + fixed discovery locations</td><td><a href="./../06-agent-systems/plugins.html">Plugins</a></td></tr><tr><td>Agent ↔ tools/data</td><td>MCP</td><td>canonical</td><td>JSON-RPC: tools/resources/prompts</td><td><a href="./mcp.html">MCP</a></td></tr><tr><td>Editor/IDE ↔ coding agent</td><td>ACP (Agent Client Protocol)</td><td>canonical</td><td>standardized editor–coding-agent communication</td><td><a href="./acp-agent-client.html">ACP</a></td></tr><tr><td>Agent ↔ user/app</td><td>AG-UI</td><td>canonical</td><td>event-stream/state/interrupt user-interaction protocol</td><td><a href="./ag-ui.html">AG-UI</a></td></tr><tr><td>Agent ↔ Agent</td><td>A2A</td><td>canonical</td><td>cross-framework agent interoperability (Card→Task→Artifact)</td><td><a href="./a2a.html">A2A</a></td></tr><tr><td>Agent ↔ rendered UI</td><td>A2UI / MCP Apps</td><td>canonical</td><td>interactive UI elements rendered inside conversations</td><td><a href="./a2ui-mcp-apps.html">A2UI and MCP Apps</a></td></tr><tr><td>discovery / registry</td><td>ARD, MCP Registry</td><td>watchlist</td><td>capability and resource discovery</td><td><a href="./watchlist.html">Protocol Watchlist</a></td></tr><tr><td>commerce (payments/settlement)</td><td>UCP, AP2, x402</td><td>watchlist</td><td>agent commerce payment rails</td><td><a href="./watchlist.html">Protocol Watchlist</a></td></tr></tbody></table><h3 id="acp-triple-homonym-disambiguation-check-this-table-before-reading-any-acp-material" tabindex="-1">ACP triple-homonym disambiguation (check this table before reading any ACP material) <a class="header-anchor" href="#acp-triple-homonym-disambiguation-check-this-table-before-reading-any-acp-material" aria-label="Permalink to &quot;ACP triple-homonym disambiguation (check this table before reading any ACP material)&quot;">​</a></h3><p>&quot;ACP&quot; is a collision-prone acronym shared by at least three different things:</p><table tabindex="0"><thead><tr><th>#</th><th>Full name</th><th>What it is</th><th>Boundary</th><th>Status</th></tr></thead><tbody><tr><td>①</td><td><strong>Agent Client Protocol</strong> (agentclientprotocol.com)</td><td>the standard protocol between editors/IDEs and coding agents; JSON-RPC over stdio locally, HTTP/WebSocket remotely; reuses MCP&#39;s JSON representations</td><td>&quot;ACP&quot; on this site&#39;s interoperability pages always means <strong>this one</strong>; details in the <a href="./acp-agent-client.html">ACP chapter</a></td><td>active (Zed and editor ecosystems)</td></tr><tr><td>②</td><td>IBM/BeeAI <strong>Agent Communication Protocol</strong></td><td>a historical agent↔agent communication scheme</td><td>folded into the A2A line; when old material mentions it, read it as an A2A predecessor</td><td>historical</td></tr><tr><td>③</td><td>OpenClaw internal <strong>Agent Communication Protocol</strong></td><td>OpenClaw&#39;s private internal protocol, unrelated to ① and ②</td><td>product implementation detail, see <a href="/zh/products/openclaw/source-code/acp.html">OpenClaw source: ACP (zh)</a></td><td>product-private</td></tr></tbody></table><p>Citation rule: unqualified &quot;ACP&quot; anywhere in this site&#39;s interoperability pages means ①; mentioning ② requires the &quot;IBM/BeeAI&quot; qualifier and a historical note; mentioning ③ requires the &quot;OpenClaw&quot; qualifier and a link into the Products area.</p><h3 id="selection-decision-table" tabindex="-1">Selection decision table <a class="header-anchor" href="#selection-decision-table" aria-label="Permalink to &quot;Selection decision table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Need</th><th>Direction</th><th>Trust domain</th><th>State need</th><th>Lowest-complexity choice</th></tr></thead><tbody><tr><td>Agent calls tools / reads data</td><td>Agent → tools</td><td>tool boundary</td><td>server process / stateless requests</td><td>MCP</td></tr><tr><td>Editor adopts a coding agent</td><td>Editor ↔ agent</td><td>local process or remote</td><td>session / streaming diffs</td><td>ACP①</td></tr><tr><td>Frontend app renders agent progress</td><td>Agent → user UI</td><td>app boundary</td><td>event stream / interrupts</td><td>AG-UI</td></tr><tr><td>Two independent agents collaborate</td><td>Agent ↔ Agent</td><td>cross-org / cross-framework</td><td>async Task/Artifact</td><td>A2A</td></tr><tr><td>Agent outputs interactive UI</td><td>Agent → rendered UI</td><td>host rendering boundary</td><td>UI payload</td><td>A2UI / MCP Apps</td></tr><tr><td>Just reusing a procedure</td><td>knowledge → context</td><td>inside host process</td><td>none</td><td>Skills (not a protocol)</td></tr><tr><td>One function inside the same host</td><td>in-process</td><td>in-process</td><td>none</td><td>a direct function call (no protocol)</td></tr></tbody></table><p>The last row is a defensive reminder: protocols solve communication and discovery <strong>across boundaries</strong>; in-process calls need functions. When the rung 6 trigger of the <a href="./../00-map/complexity-ladder.html">Complexity Decision Ladder</a> has not fired, introduce none of the protocols on this page.</p><h3 id="combination-example-the-protocol-jigsaw-of-one-real-collaboration" tabindex="-1">Combination example: the protocol jigsaw of one real collaboration <a class="header-anchor" href="#combination-example-the-protocol-jigsaw-of-one-real-collaboration" aria-label="Permalink to &quot;Combination example: the protocol jigsaw of one real collaboration&quot;">​</a></h3>',11)),(o(),i(d,null,{default:e(()=>[s(n,{id:"mermaid-431",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20U%5B%22User%22%5D%20--%20%22AG-UI%20event%20stream%22%20--%3E%20A%5B%22local%20agent%22%5D%0A%20%20%20%20A%20--%20%22MCP%22%20--%3E%20T%5B%22tool%2Fdata%20server%22%5D%0A%20%20%20%20A%20--%20%22A2A%22%20--%3E%20B%5B%22another%20org's%20agent%22%5D%0A%20%20%20%20A%20--%20%22A2UI%2FMCP%20Apps%22%20--%3E%20R%5B%22rendered%20UI%20in%20conversation%22%5D%0A%20%20%20%20A%20--%20%22Skills%22%20--%3E%20K%5B%22procedure%20knowledge%20package%22%5D%0A"})]),fallback:e(()=>[...t[1]||(t[1]=[r(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=a('<p>One session can use four directions at once: AG-UI carries user-facing progress, MCP connects tools, A2A delegates subtasks to a remote agent, and Skills decide &quot;which steps to follow&quot;. The protocols complement each other; &quot;one protocol for everything&quot; is never a reasonable architecture.</p><h3 id="when-to-use-when-not-to" tabindex="-1">When to use / when not to <a class="header-anchor" href="#when-to-use-when-not-to" aria-label="Permalink to &quot;When to use / when not to&quot;">​</a></h3><ul><li>Use: any selection for cross-process/cross-org/cross-trust-domain connectivity; reviewing &quot;should we adopt protocol X&quot;.</li><li>Do not use: learning a protocol&#39;s internal message structures — go to its detail page.</li></ul><p>Historical milestones: this map was frozen in 2026-09 with Issue #116; each protocol&#39;s own versions (MCP 2026-07-28, A2A 1.0.0, ACP v1 stable + v2 Draft, Agent Plugins 1.0.0) are maintained on their detail pages (re-checked 2026-09-01: no version drift for MCP and A2A; ACP has a v2 Draft — see its detail page).</p><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><p>This page is a selection map with no runnable artifact; &quot;usage&quot; = a decision drill (paper only, ≤15 minutes). Acceptance: all four scenarios resolve to a unique protocol with a stated reason to reject the others.</p><h3 id="drill-four-scenarios" tabindex="-1">Drill: four scenarios <a class="header-anchor" href="#drill-four-scenarios" aria-label="Permalink to &quot;Drill: four scenarios&quot;">​</a></h3><p><strong>Scenario A</strong>: swap in a new coding agent inside VS Code without writing integration code.</p><ul><li>Expected: ACP①. The direction is Editor ↔ coding agent.</li><li>Rejection check: not MCP (that is Agent ↔ tools); not A2A (the two ends are not two autonomous agents).</li></ul><p><strong>Scenario B</strong>: let your agent read and write the company wiki and ticketing system.</p><ul><li>Expected: MCP. The direction is Agent ↔ tools/data.</li><li>Rejection check: if the wiki only needs &quot;which steps to follow when querying&quot;, that is Skills; connection and procedure are two directions.</li></ul><p><strong>Scenario C</strong>: two departments&#39; agents (different frameworks) must exchange long-running tasks.</p><ul><li>Expected: A2A. The direction is Agent ↔ Agent across team trust domains with async tasks.</li><li>Rejection check: for subtask delegation inside one runtime, use the runtime&#39;s native subagent mechanism — no A2A.</li></ul><p><strong>Scenario D</strong>: the agent&#39;s analysis must stream live into your React app, with interrupt support.</p><ul><li>Expected: AG-UI. The direction is an Agent → user-interface event stream.</li><li>Rejection check: if it is just &quot;render a chart inside the chat&quot;, that is A2UI / MCP Apps host rendering, not an app-level event stream.</li></ul><h3 id="usage-boundary" tabindex="-1">Usage boundary <a class="header-anchor" href="#usage-boundary" aria-label="Permalink to &quot;Usage boundary&quot;">​</a></h3><ul><li>This map decides <strong>which direction</strong>; each protocol&#39;s versions, messages, and security live on its detail page.</li><li>Watchlist protocols never enter the decision table: without production evidence they are recorded, not recommended.</li></ul><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><h3 id="why-organize-by-connection-direction-instead-of-feature-strength" tabindex="-1">Why organize by &quot;connection direction&quot; instead of &quot;feature strength&quot; <a class="header-anchor" href="#why-organize-by-connection-direction-instead-of-feature-strength" aria-label="Permalink to &quot;Why organize by &quot;connection direction&quot; instead of &quot;feature strength&quot;&quot;">​</a></h3><p>Protocol cost comes from <strong>boundaries</strong>, not features: every protocol boundary adds a set of version negotiation, authorization, and failure semantics. Connection direction is the natural coordinate of a boundary — the identity of the two ends (user/editor/agent/tool) determines who initiates, who renders, who pays, and who is accountable. Feature comparisons (whose messages are richer) are meaningless without a direction constraint: however rich AG-UI&#39;s event stream, it cannot replace MCP&#39;s tool authorization.</p><h3 id="mcp-and-a2a-complement-not-compete-official-position" tabindex="-1">MCP and A2A complement, not compete (official position) <a class="header-anchor" href="#mcp-and-a2a-complement-not-compete-official-position" aria-label="Permalink to &quot;MCP and A2A complement, not compete (official position)&quot;">​</a></h3><p>The A2A documentation states explicitly: &quot;MCP and A2A are not competitors — they are highly complementary&quot; — <strong>MCP covers agent↔tool</strong> (connecting APIs and resources), <strong>A2A covers agent↔agent</strong> (discovery, delegation, sharing results). A selection conflict never requires choosing between them (retrievedAt 2026-09-01).</p><h3 id="admission-rule-for-the-observation-zone" tabindex="-1">Admission rule for the observation zone <a class="header-anchor" href="#admission-rule-for-the-observation-zone" aria-label="Permalink to &quot;Admission rule for the observation zone&quot;">​</a></h3><p>A protocol enters the watchlist with only &quot;an official spec or an active maintainer&quot;; promotion into the canonical decision table requires real consumption evidence from learn-ai or a sibling, or multiple independent implementations in the ecosystem. ARD, MCP Registry, UCP, AP2, and x402 all remain in the observation zone; details and verification dates live in the <a href="./watchlist.html">Protocol Watchlist</a>.</p><h3 id="spec-requirements-vs-local-measurement" tabindex="-1">Spec requirements vs local measurement <a class="header-anchor" href="#spec-requirements-vs-local-measurement" aria-label="Permalink to &quot;Spec requirements vs local measurement&quot;">​</a></h3><p>This page is a selection pattern with no spec to implement; the &quot;spec vs measurement&quot; columns live on the four canonical protocol detail pages (<a href="./mcp.html">MCP</a>, <a href="./a2a.html">A2A</a>, <a href="./acp-agent-client.html">ACP</a>, <a href="./ag-ui.html">AG-UI</a>).</p><h2 id="_4-development" tabindex="-1">4. Development <a class="header-anchor" href="#_4-development" aria-label="Permalink to &quot;4. Development&quot;">​</a></h2><p>This page has no code integration; &quot;development&quot; = using the map as an architecture-review gate.</p><h3 id="symptom-→-evidence-→-action-→-done-when" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: a review argues &quot;MCP or A2A&quot; with feature lists on both sides. <strong>Evidence</strong>: nobody stated the connection direction first — the identity of the two ends (agent↔tool or agent↔agent) is undefined. <strong>Action</strong>: fill in the direction/trust-domain/state columns of the selection table first; the candidate set collapses to one. <strong>Done when</strong>: the design document states the two ends and the direction, and the conclusion follows directly from the table.</p><h3 id="symptom-→-evidence-→-action-→-done-when-1" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when-1" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: readers understand &quot;ACP&quot; in a document differently and the thread derails. <strong>Evidence</strong>: no qualifier — it could be Agent Client Protocol, the IBM historical ACP, or the OpenClaw private ACP. <strong>Action</strong>: add qualifiers per the disambiguation table; the site default is ①, the others always carry prefixes. <strong>Done when</strong>: every occurrence of ACP in that document maps to exactly one row of the table.</p><h3 id="symptom-→-evidence-→-action-→-done-when-2" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when-2" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: a proposal cites a watchlist protocol (e.g. x402) as a critical-path dependency. <strong>Evidence</strong>: the protocol has no consumption evidence on this site and is absent from the decision table. <strong>Action</strong>: downgrade it to an &quot;observation item&quot;: move the main path to a canonical protocol or an explicit custom layer, and list the watchlist protocol as an optional experiment. <strong>Done when</strong>: the critical path depends on no watchlist entry; the experiment has an independent switch and a fallback.</p><h3 id="anti-patterns" tabindex="-1">Anti-patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-patterns&quot;">​</a></h3><ul><li><strong>Picking a protocol before fixing the direction</strong>: substituting feature lists for connection-direction analysis.</li><li><strong>One word, three meanings</strong>: using ACP without a qualifier.</li><li><strong>Treating the observation zone as a shelf</strong>: adopting an evidence-free new protocol on the critical path.</li></ul><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><p>Four-level reading route:</p><ul><li><strong>Beginner</strong>: read this page; retell the landscape table and the triple disambiguation.</li><li><strong>Builder</strong>: run the zero-dependency server+client fixture in <a href="./mcp.html">MCP</a>; then read ACP/AG-UI by direction.</li><li><strong>Operator</strong>: use the selection table as a review template; track protocol version announcements.</li><li><strong>Researcher</strong>: read the A2A site&#39;s &quot;How A2A Works with MCP&quot; and each spec&#39;s original text to verify the complementarity position.</li></ul><h3 id="resource-table" tabindex="-1">Resource table <a class="header-anchor" href="#resource-table" aria-label="Permalink to &quot;Resource table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Evidence level</th><th>Canonical URL</th><th>Use</th><th>Supported claim</th><th>Next</th></tr></thead><tbody><tr><td>A2A site (incl. MCP complementarity)</td><td>L0 (official)</td><td><a href="https://a2a-protocol.org/latest/" target="_blank" rel="noreferrer">https://a2a-protocol.org/latest/</a></td><td>the official statement of the A2A/MCP division</td><td>&quot;MCP↔tools, A2A↔agents, complementary not competing&quot; (retrievedAt 2026-09-01)</td><td><a href="./a2a.html">A2A</a></td></tr><tr><td>Agent Client Protocol site</td><td>L0 (official)</td><td><a href="https://agentclientprotocol.com/" target="_blank" rel="noreferrer">https://agentclientprotocol.com/</a></td><td>the definition of ACP①</td><td>&quot;standardizes communication between code editors/IDEs and coding agents&quot; (retrievedAt 2026-09-01)</td><td><a href="./acp-agent-client.html">ACP</a></td></tr><tr><td>MCP specification</td><td>L0 (official spec)</td><td><a href="https://modelcontextprotocol.io/specification/latest" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/latest</a></td><td>the spec for the agent↔tools direction</td><td>protocol responsibilities and versions (retrievedAt 2026-09-01)</td><td><a href="./mcp.html">MCP</a></td></tr><tr><td>AG-UI docs</td><td>L0 (official)</td><td><a href="https://docs.ag-ui.com/introduction" target="_blank" rel="noreferrer">https://docs.ag-ui.com/introduction</a></td><td>the spec for the agent↔user direction</td><td>event/state/interrupt model (retrievedAt 2026-09-01, re-check on detail page)</td><td><a href="./ag-ui.html">AG-UI</a></td></tr></tbody></table><h3 id="active-falsification-and-open-questions" tabindex="-1">Active falsification and open questions <a class="header-anchor" href="#active-falsification-and-open-questions" aria-label="Permalink to &quot;Active falsification and open questions&quot;">​</a></h3><ul><li>Falsification entry: if a real requirement maps to two protocols (or zero) under the selection table, the map&#39;s direction coordinates are incomplete — revise the table rather than hiding the scenario.</li><li>Open: promotion reviews for watchlist protocols (ARD/Registry/UCP/AP2/x402) continue in the <a href="./watchlist.html">Protocol Watchlist</a>; the A2UI vs MCP Apps boundary is maintained on <a href="./a2ui-mcp-apps.html">its detail page</a>.</li></ul><h3 id="learn-ai-stops-here-where-to-go-next" tabindex="-1">learn-ai stops here / where to go next <a class="header-anchor" href="#learn-ai-stops-here-where-to-go-next" aria-label="Permalink to &quot;learn-ai stops here / where to go next&quot;">​</a></h3><ul><li>Principles and fixtures of the four canonical protocols: <a href="./mcp.html">MCP</a>, <a href="./a2a.html">A2A</a>, <a href="./acp-agent-client.html">ACP</a>, <a href="./ag-ui.html">AG-UI</a>.</li><li>The prerequisite overview: <a href="./../00-map/complexity-ladder.html">Complexity Decision Ladder</a> — if rung 6 has not fired, you need none of this page&#39;s protocols.</li></ul>',45))])}const C=l(p,[["render",u]]);export{v as __pageData,C as default};
